             Event::SystemExplored { star: StarId(10) },
             Event::ResearchCompleted { tech: TechId(1) },
             Event::FirstContact {
                 with_empire: EmpireId(2),
             },
         ];
         let a = generate_dispatch(0, &events, &state).unwrap();
