 /// Grant a completed technology to an empire so tech-gated builds are reachable.
 fn give_empire_tech(engine: &mut Engine, empire: EmpireId, tech: TechId) {
     let completed = &mut engine
         .state
         .empires
         .get_mut(&empire)
         .unwrap()
         .research
         .completed;
     if !completed.contains(&tech) {
         completed.push(tech);
     }
 }

