         directive: SectorDirective,
     },
     /// A colony's build-queue automation mode was changed by the player
     ColonyAutomationModeSet {
         colony: ColonyId,
         automation: ColonyAutomation,
     },
     /// Automation queued a build item for a sector-guided colony with an empty queue
     ColonyAutomationQueued {
         colony: ColonyId,
         item: BuildItem,
         directive: SectorDirective,
     },
     /// A rally point was set for a colony
     RallyPointSet { colony: ColonyId, star: StarId },
     /// The rally point for a colony was cleared
     RallyPointCleared { colony: ColonyId },
     /// A standing fleet order was set
     FleetOrderSet { fleet: FleetId, order: FleetOrder },
     /// A fleet's strategic role was changed.
     FleetRoleChanged { fleet: FleetId, role: FleetRole },
     /// A fleet's formation posture was changed.
     FleetFormationChanged {
         fleet: FleetId,
         formation: FleetFormation,
     },
     /// A fleet was renamed.
     FleetRenamed { fleet: FleetId, name: String },
     /// A newly produced ship was automatically routed toward the colony's rally point
     ShipRoutedToRallyPoint {
         fleet: FleetId,
         colony: ColonyId,
         from: StarId,
         to: StarId,
         turns_remaining: u32,
     },
     /// A colony has come under blockade by a hostile empire
     BlockadeStarted {
         /// The blockaded colony
         colony: ColonyId,
         /// The star system where the blockade is taking effect
         star: StarId,
         /// The empire imposing the blockade
         by_empire: EmpireId,
     },
     /// A specific fleet established a blockade over an enemy colony.
     BlockadeFleetEstablished {
         fleet: FleetId,
         colony: ColonyId,
         star: StarId,
         by_empire: EmpireId,
     },
     /// A colony's blockade has been lifted
     BlockadeEnded {
         /// The colony that was blockaded
         colony: ColonyId,
         /// The star system where the blockade ended
         star: StarId,
     },
     /// A major victory-path progress milestone was reached.
     VictoryProgressMilestone {
         path: VictoryPath,
         empire: EmpireId,
         progress_percent: u8,
     },
     /// A winner has been determined by configured victory conditions.
     VictoryAchieved {
         winner: EmpireId,
         path: VictoryPath,
         turn: u32,
     },
     /// A player or AI empire created a custom ship design.
     ShipDesignCreated {
         empire: EmpireId,
         design_id: CustomDesignId,
         hull_id: HullId,
         name: String,
     },
     /// A custom ship design was marked obsolete and removed.
     ShipDesignDeleted {
         empire: EmpireId,
         design_id: CustomDesignId,
     },
     /// Validation of a custom ship design failed.
     ShipDesignInvalid {
         empire: EmpireId,
         hull_id: HullId,
         reason: String,
     },
     /// A ship built from a custom design was completed at a colony.
     CustomShipConstructed {
         empire: EmpireId,
         colony: ColonyId,
         design_id: CustomDesignId,
         fleet: FleetId,
     },
     /// A fleet intentfully assembled as an invasion task force.
     InvasionFleetAssembled {
         empire: EmpireId,
         fleet: FleetId,
         star: StarId,
     },
     /// Combat engagement has started between two fleets.
     FleetEngagementStarted {
         star: StarId,
         fleet_a: FleetId,
         fleet_b: FleetId,
     },
     /// A fleet disengaged from combat and is retreating.
     FleetRetreatTriggered {
         fleet: FleetId,
         from_star: StarId,
         to_star: StarId,
         remaining_integrity: u32,
     },
+    /// Trade routes were computed for an empire this turn.
+    TradeRoutesComputed {
+        empire: EmpireId,
+        route_count: usize,
+        total_value: i64,
+        disrupted_count: usize,
+    },
+    /// A previously-connected trade route was disrupted.
+    TradeRouteDisrupted {
+        empire: EmpireId,
+        from: StarId,
+        to: StarId,
+        reason: TradeDisruptionReason,
+    },
+    /// A previously-disrupted trade route was restored.
+    TradeRouteRestored {
+        empire: EmpireId,
+        from: StarId,
+        to: StarId,
+    },
 }

 impl Event {
     /// Create an error event
     pub fn error(message: impl Into<String>) -> Self {
         Event::Error {
             message: message.into(),
         }
     }

     /// Convert event to a log message
     pub fn to_log_message(&self) -> String {
         match self {
             Event::TurnAdvanced { new_turn } => format!("Turn {} begins", new_turn),
             Event::ColonyFocusSet { colony } => format!("Colony {} focus updated", colony.0),
             Event::FleetMoved { fleet, from, to } => {
                 format!("Fleet {} moved from {} to {}", fleet.0, from.0, to.0)
             }
             Event::BuildQueued { colony, item } => {
                 format!(
                     "Colony {} queued {} ({})",
                     colony.0,
                     item.name(),
                     item.category_name()
                 )
             }
             Event::BuildCancelled { colony } => {
                 format!("Colony {} cancelled build", colony.0)
             }
             Event::BuildCompleted { colony, item } => {
                 format!(
                     "Colony {} completed {} ({})",
                     colony.0,
                     item.name(),
                     item.category_name()
                 )
             }
             Event::ColonyProduced {
                 colony,
                 credits,
                 research,
                 food,
                 // industry and maintenance are available for UI/summary display
                 // but omitted from the log message to keep it concise.
                 industry: _,
                 maintenance: _,
             } => {
                 format!(
                     "Colony {} produced {} credits, {} research, {} food",
                     colony.0, credits, research, food
                 )
             }
             Event::FleetCreated { fleet, location } => {
                 format!("Fleet {} created at star {}", fleet.0, location.0)
             }
             Event::ResearchSelected { tech } => {
                 format!("Research started: tech {}", tech.0)
             }
             Event::ResearchQueued { tech } => {
                 format!("Research queued: tech {}", tech.0)
             }
             Event::ResearchQueueRemoved { tech } => {
                 format!("Research queue removed: tech {}", tech.0)
             }
             Event::ResearchQueueReordered {
                 tech,
                 from_index,
                 to_index,
             } => {
                 format!(
                     "Research queue reordered: tech {} moved {}→{}",
                     tech.0, from_index, to_index
                 )
             }
             Event::ResearchQueueCleared { removed_count } => {
                 format!("Research queue cleared: {} removed", removed_count)
             }
             Event::ScienceGenerated { empire, amount } => {
                 format!("Empire {} generated {} science this turn", empire.0, amount)
             }
             Event::ResearchProgress {
                 tech,
                 gained,
                 total,
                 cost,
             } => {
                 format!(
                     "Research: +{} rp on tech {} ({}/{} rp)",
                     gained, tech.0, total, cost
                 )
             }
             Event::ResearchCompleted { tech } => {
                 format!("Research complete: tech {}", tech.0)
             }
             Event::QueuedResearchStarted { tech } => {
                 format!("Queued research started: tech {}", tech.0)
             }
             Event::QueuedResearchSkipped { tech, reason } => {
                 format!("Queued research skipped: tech {} ({})", tech.0, reason)
             }
             Event::ResearchCompletedWithQueueTransition { completed, started } => match started {
                 Some(tech) => format!(
                     "Research transition: tech {} complete, queued tech {} started",
                     completed.0, tech.0
                 ),
                 None => format!(
                     "Research transition: tech {} complete, no queued tech started",
                     completed.0
                 ),
             },
             Event::HyperspaceCartographyUnlocked { empire } => {
                 format!(
                     "Empire {} unlocked Hyperspace Cartography — known lanes are now usable",
                     empire.0
                 )
             }
             Event::ScoutDispatched {
                 fleet,
                 destination,
                 turns_remaining,
             } => {
                 format!(
                     "Scout {} dispatched to system {} ({} turns)",
                     fleet.0, destination.0, turns_remaining
                 )
             }
             Event::SurveyStarted {
                 fleet,
                 star,
                 planet_index,
                 turns_remaining,
             } => {
                 format!(
                     "Science ship {} started survey at system {} orbit {} ({} turns)",
                     fleet.0,
                     star.0,
                     planet_index + 1,
                     turns_remaining
                 )
             }
             Event::SystemExplored { star } => {
                 format!("System {} explored", star.0)
             }
             Event::PlanetSurveyCompleted { star, planet_index } => {
                 format!(
                     "Survey completed: system {} orbit {}",
                     star.0,
                     planet_index + 1
                 )
             }
             Event::AncientRuinsDiscovered { star, planet_index } => {
                 format!(
                     "DISCOVERY: Ancient Ruins found at system {} orbit {} — +2 science per turn",
                     star.0,
                     planet_index + 1
                 )
             }
             Event::PlanetSpecialDiscovered {
                 star,
                 planet_index,
                 special,
             } => {
                 format!(
                     "DISCOVERY: {} identified at system {} orbit {} — {}",
                     special.name(),
                     star.0,
                     planet_index + 1,
                     special.effect_summary()
                 )
             }
             Event::AnomalyDetected {
                 star,
                 planet_index,
                 anomaly,
             } => {
                 format!(
                     "ANOMALY: {} detected at system {} orbit {} [{}] — {}",
                     anomaly.name(),
                     star.0,
                     planet_index + 1,
                     anomaly.formatted_risk(),
                     anomaly.description()
                 )
             }
             Event::StrategicResourceDiscovered {
                 star,
                 planet_index,
                 resource,
             } => {
                 format!(
                     "DISCOVERY: {} identified at system {} orbit {}",
                     resource.name(),
                     star.0,
                     planet_index + 1
                 )
             }
             Event::FleetDeparted {
                 fleet,
                 from,
                 to,
                 turns_remaining,
             } => {
                 format!(
                     "Fleet {} departed from {} toward {} ({} turns)",
                     fleet.0, from.0, to.0, turns_remaining
                 )
             }
             Event::FleetArrived { fleet, star } => {
                 format!("Fleet {} arrived at system {}", fleet.0, star.0)
             }
             Event::HyperspaceLaneUsed {
                 empire,
                 fleet,
                 from,
                 to,
             } => {
                 format!(
                     "Empire {}: Fleet {} used hyperspace lane {} ↔ {}",
                     empire.0, fleet.0, from.0, to.0
                 )
             }
             Event::ColonizationStarted {
                 empire,
                 fleet,
                 star,
                 planet_index,
             } => {
                 format!(
                     "Empire {} started colonization with fleet {} at system {} orbit {}",
                     empire.0,
                     fleet.0,
                     star.0,
                     planet_index + 1
                 )
             }
             Event::ColonizationCompleted {
                 empire,
                 fleet: _,
                 star,
                 planet_index,
                 colony,
             } => {
                 format!(
                     "Empire {} founded colony {} at system {} orbit {}",
                     empire.0,
                     colony.0,
                     star.0,
                     planet_index + 1
                 )
             }
             Event::InvasionSucceeded {
                 attacker,
                 defender,
                 fleet,
                 star,
                 planet_index,
                 colony,
                 transports_lost,
             } => {
                 format!(
                     "INVASION SUCCESS: Empire {} captured colony {} from Empire {} at system {} orbit {} using transport {} (lost {})",
                     attacker.0,
                     colony.0,
                     defender.0,
                     star.0,
                     planet_index + 1,
                     fleet.0,
                     transports_lost
                 )
             }
             Event::InvasionFailed {
                 attacker,
                 defender,
                 fleet,
                 star,
                 planet_index,
                 colony,
                 invasion_strength,
                 defense_strength,
                 transports_lost,
                 reason,
             } => {
                 format!(
                     "INVASION FAILED: Empire {} vs Empire {} at colony {} (system {} orbit {}) using transport {} — {} (strength {} vs {}, lost {})",
                     attacker.0,
                     defender.0,
                     colony.0,
                     star.0,
                     planet_index + 1,
                     fleet.0,
                     reason,
                     invasion_strength,
                     defense_strength,
                     transports_lost
                 )
             }
             Event::EconomySummary {
                 empire,
                 credits_income,
                 maintenance,
                 food_produced,
                 food_consumed,
             } => {
                 format!(
                     "Empire {} economy: +{} credits income, -{} maintenance, +{} food, -{} consumed",
                     empire.0, credits_income, maintenance, food_produced, food_consumed
                 )
             }
             Event::ColonyStatusWarning {
                 colony,
                 food_deficit,
                 housing_deficit,
                 unemployed,
             } => format!(
                 "WARNING: Colony {} pressure — food deficit {}, housing deficit {}, unemployed {}",
                 colony.0, food_deficit, housing_deficit, unemployed
             ),
             Event::PopulationGrew {
                 colony,
                 new_population,
             } => format!("Colony {} population grew to {}", colony.0, new_population),
             Event::FoodShortage { empire, deficit } => {
                 format!(
                     "WARNING: Empire {} food shortage — deficit {}",
                     empire.0, deficit
                 )
             }
             Event::CreditDeficit { empire, deficit } => {
                 format!(
                     "WARNING: Empire {} credit deficit — deficit {}",
                     empire.0, deficit
                 )
             }
             Event::ColonyIsolated { colony } => {
                 format!(
                     "WARNING: Colony {} is now isolated from trade network",
                     colony.0
                 )
             }
             Event::ColonyReconnected { colony } => {
                 format!("Colony {} reconnected to trade network", colony.0)
             }
             Event::ColonyUnrestChanged {
                 colony,
                 from,
                 to,
                 causes,
                 rebellion_risk_bp,
             } => {
                 let cause_text = if causes.is_empty() {
                     "no active causes".to_string()
                 } else {
                     causes
                         .iter()
                         .map(|cause| cause.label())
                         .collect::<Vec<_>>()
                         .join(", ")
                 };
                 format!(
                     "UNREST: Colony {} {} → {} (risk {:.1}%, causes: {})",
                     colony.0,
                     from.label(),
                     to.label(),
                     f64::from(*rebellion_risk_bp) / 100.0,
                     cause_text
                 )
             }
             Event::Error { message } => format!("Error: {}", message),
             Event::AiResearchSelected { empire, tech } => {
                 format!("AI Empire {}: researching tech {}", empire.0, tech.0)
             }
             Event::AiBuildQueued {
                 empire,
                 colony,
                 item,
             } => {
                 format!(
                     "AI Empire {}: queued {} at colony {}",
                     empire.0,
                     item.name(),
                     colony.0
                 )
             }
             Event::AiScoutDispatched {
                 empire,
                 fleet,
                 destination,
             } => {
                 format!(
                     "AI Empire {}: scout {} dispatched to system {}",
                     empire.0, fleet.0, destination.0
                 )
             }
             Event::AiCombatFleetDispatched {
                 empire,
                 fleet,
                 destination,
             } => {
                 format!(
                     "AI Empire {}: combat fleet {} dispatched toward system {}",
                     empire.0, fleet.0, destination.0
                 )
             }
             Event::AiColonized {
                 empire,
                 star,
                 planet_index,
                 colony,
             } => {
                 format!(
                     "AI Empire {}: colonized system {} planet {} (colony {})",
                     empire.0, star.0, planet_index, colony.0
                 )
             }
             Event::FirstContact { with_empire } => {
                 format!(
                     "FIRST CONTACT: Diplomatic contact established with Empire {}",
                     with_empire.0
                 )
             }
             Event::DiplomaticCommunicationCreated {
                 communication_id,
                 from_empire,
                 to_empire,
                 communication_type,
             } => format!(
                 "Diplomatic communication {}: {:?} from Empire {} to Empire {}",
                 communication_id, communication_type, from_empire.0, to_empire.0
             ),
             Event::TreatyProposed {
                 from_empire,
                 to_empire,
                 treaty_type,
             } => format!(
                 "Empire {} proposed {} to Empire {}",
                 from_empire.0,
                 treaty_type.label(),
                 to_empire.0
             ),
             Event::TreatyAccepted {
                 from_empire,
                 to_empire,
                 treaty_type,
             } => format!(
                 "Empire {} accepted {} with Empire {}",
                 to_empire.0,
                 treaty_type.label(),
                 from_empire.0
             ),
             Event::TreatyRejected {
                 from_empire,
                 to_empire,
                 treaty_type,
             } => format!(
                 "Empire {} rejected {} from Empire {}",
                 to_empire.0,
                 treaty_type.label(),
                 from_empire.0
             ),
             Event::TreatySigned {
                 with_empire,
                 treaty_type,
                 expires_turn,
             } => format!(
                 "{} signed with Empire {} (expires turn {})",
                 treaty_type.label(),
                 with_empire.0,
                 expires_turn
             ),
             Event::TreatyExpired {
                 with_empire,
                 treaty_type,
             } => format!(
                 "{} with Empire {} expired",
                 treaty_type.label(),
                 with_empire.0
             ),
             Event::TreatyCancelled {
                 with_empire,
                 treaty_type,
             } => format!(
                 "{} with Empire {} cancelled",
                 treaty_type.label(),
                 with_empire.0
             ),
             Event::WarningIssued {
                 from_empire,
                 to_empire,
             } => format!(
                 "Empire {} issued warning to Empire {}",
                 from_empire.0, to_empire.0
             ),
             Event::TributeDemanded {
                 from_empire,
                 to_empire,
             } => format!(
                 "Empire {} demanded tribute from Empire {}",
                 from_empire.0, to_empire.0
             ),
             Event::TributeRefused {
                 from_empire,
                 to_empire,
             } => format!(
                 "Empire {} refused tribute demand from Empire {}",
                 to_empire.0, from_empire.0
             ),
             Event::WarDeclared { attacker, defender } => {
                 format!(
                     "WAR DECLARED: Empire {} declared war on Empire {}",
                     attacker.0, defender.0
                 )
             }
             Event::PeaceSigned {
                 with_empire,
                 truce_expires_turn,
             } => format!(
                 "Peace signed with Empire {} (truce until turn {})",
                 with_empire.0, truce_expires_turn
             ),
             Event::RelationshipStateChanged {
                 with_empire,
                 from,
                 to,
             } => format!(
                 "Diplomatic status with Empire {} changed: {} → {}",
                 with_empire.0,
                 from.label(),
                 to.label()
             ),
             Event::IntelGained {
                 with_empire,
                 gained,
                 new_level,
                 sources,
             } => format!(
                 "Intelligence on Empire {} improved by {} point(s) via {} — level {}",
                 with_empire.0,
                 gained,
                 sources
                     .iter()
                     .map(|source| source.label())
                     .collect::<Vec<_>>()
                     .join(", "),
                 new_level.label()
             ),
             Event::EspionageMissionUnavailable {
                 with_empire,
                 mission,
             } => format!(
                 "{} against Empire {} reserved for future slice",
                 mission.label(),
                 with_empire.0
             ),
             Event::CombatResolved {
                 star,
                 fleet_a,
                 empire_a,
                 fleet_b,
                 empire_b,
                 strength_a,
                 strength_b,
                 integrity_a_remaining,
                 integrity_b_remaining,
                 fleet_a_destroyed,
                 fleet_b_destroyed,
             } => {
                 let result = match (fleet_a_destroyed, fleet_b_destroyed) {
                     (true, true) => "both fleets destroyed".to_string(),
                     (true, false) => format!(
                         "Fleet {} (Empire {}) destroyed; Fleet {} (Empire {}) survives at {}% integrity",
                         fleet_a.0, empire_a.0, fleet_b.0, empire_b.0, integrity_b_remaining
                     ),
                     (false, true) => format!(
                         "Fleet {} (Empire {}) survives at {}% integrity; Fleet {} (Empire {}) destroyed",
                         fleet_a.0, empire_a.0, integrity_a_remaining, fleet_b.0, empire_b.0
                     ),
                     (false, false) => format!(
                         "Fleet {} (Empire {}) at {}% integrity; Fleet {} (Empire {}) at {}% integrity",
                         fleet_a.0,
                         empire_a.0,
                         integrity_a_remaining,
                         fleet_b.0,
                         empire_b.0,
                         integrity_b_remaining
                     ),
                 };
                 format!(
                     "COMBAT at system {}: Fleet {} (Str:{}) vs Fleet {} (Str:{}) — {}",
                     star.0, fleet_a.0, strength_a, fleet_b.0, strength_b, result
                 )
             }
             Event::ColonyRoleChanged { colony, role } => {
                 format!("Colony {}: role set to {}", colony.0, role.name())
             }
             Event::AiColonyRoleAssigned {
                 empire,
                 colony,
                 role,
             } => {
                 format!(
                     "AI Empire {}: colony {} assigned role {}",
                     empire.0,
                     colony.0,
                     role.name()
                 )
             }
             Event::SectorDirectiveSet { sector, directive } => {
                 format!("Sector {}: directive set to {}", sector.0, directive.name())
             }
             Event::ColonyAutomationModeSet { colony, automation } => {
                 format!(
                     "Colony {}: automation set to {}",
                     colony.0,
                     automation.name()
                 )
             }
             Event::ColonyAutomationQueued {
                 colony,
                 item,
                 directive,
             } => {
                 format!(
                     "Colony {}: automation ({}) queued {}",
                     colony.0,
                     directive.name(),
                     item.name()
                 )
             }
             Event::RallyPointSet { colony, star } => {
                 format!("Colony {}: rally point set to system {}", colony.0, star.0)
             }
             Event::RallyPointCleared { colony } => {
                 format!("Colony {}: rally point cleared", colony.0)
             }
             Event::FleetOrderSet { fleet, order } => match order {
                 FleetOrder::Hold => format!("Fleet {}: order set to Hold", fleet.0),
                 FleetOrder::MoveToSystem(star) => {
                     format!("Fleet {}: order set — moving to system {}", fleet.0, star.0)
                 }
             },
             Event::FleetRoleChanged { fleet, role } => {
                 format!("Fleet {}: role set to {}", fleet.0, role.label())
             }
             Event::FleetFormationChanged { fleet, formation } => {
                 format!("Fleet {}: formation set to {}", fleet.0, formation.label())
             }
             Event::FleetRenamed { fleet, name } => {
                 format!("Fleet {} renamed to '{}'", fleet.0, name)
             }
             Event::ShipRoutedToRallyPoint {
                 fleet,
                 colony,
                 from: _,
                 to,
                 turns_remaining,
             } => {
                 format!(
                     "Fleet {} (from colony {}) routed to rally point system {} ({} turns)",
                     fleet.0, colony.0, to.0, turns_remaining
                 )
             }
             Event::BlockadeStarted {
                 colony,
                 star,
                 by_empire,
             } => {
                 format!(
                     "WARNING: Colony {} at system {} is under blockade by Empire {}",
                     colony.0, star.0, by_empire.0
                 )
             }
             Event::BlockadeFleetEstablished {
                 fleet,
                 colony,
                 star,
                 by_empire,
             } => format!(
                 "Fleet {} (Empire {}) established blockade on colony {} at system {}",
                 fleet.0, by_empire.0, colony.0, star.0
             ),
             Event::BlockadeEnded { colony, star } => {
                 format!("Colony {} at system {} blockade lifted", colony.0, star.0)
             }
             Event::VictoryProgressMilestone {
                 path,
                 empire,
                 progress_percent,
             } => {
                 format!(
                     "VICTORY MILESTONE: Empire {} reached {}% toward {} victory",
                     empire.0,
                     progress_percent,
                     path.label()
                 )
             }
             Event::VictoryAchieved { winner, path, turn } => {
                 format!(
                     "VICTORY ACHIEVED: Empire {} won via {} on turn {}",
                     winner.0,
                     path.label(),
                     turn
                 )
             }
             Event::ShipDesignCreated {
                 empire,
                 design_id,
                 hull_id,
                 name,
             } => {
                 format!(
                     "Empire {}: custom design {} '{}' created (hull {})",
                     empire.0, design_id.0, name, hull_id.0
                 )
             }
             Event::ShipDesignDeleted { empire, design_id } => {
                 format!("Empire {}: custom design {} deleted", empire.0, design_id.0)
             }
             Event::ShipDesignInvalid {
                 empire,
                 hull_id,
                 reason,
             } => {
                 format!(
                     "Empire {}: ship design invalid for hull {} — {}",
                     empire.0, hull_id.0, reason
                 )
             }
             Event::CustomShipConstructed {
                 empire,
                 colony,
                 design_id,
                 fleet,
             } => {
                 format!(
                     "Empire {}: custom ship (design {}) completed at colony {} as fleet {}",
                     empire.0, design_id.0, colony.0, fleet.0
                 )
             }
