             PlanetClass::Barren => "Barren",
         }
     }

     /// Flat science bonus per turn for colonies on this planet class.
     ///
     /// Frozen worlds favour computation; all other classes provide no bonus.
     pub fn science_bonus(&self) -> i64 {
         match self {
