         match self {
             ColonyUnrestState::Calm => 100,
             ColonyUnrestState::Strained => 110,
             ColonyUnrestState::Unrest => 125,
             ColonyUnrestState::RevoltRisk => 145,
         }
     }

     pub fn base_rebellion_risk_bp(self) -> u16 {
