             FleetSupplyState::Supplied => "No logistics penalty",
             FleetSupplyState::Extended => "-10% attack, -5% defense, +25% travel, -25% invasion",
             FleetSupplyState::OutOfSupply => {
                 "-25% attack, -20% defense, +60% travel, cannot invade"
             }
         }
     }
 }

