pub fn recompute_empire_trade_routes(&self) -> (BTreeMap<EmpireId, Vec<TradeRoute>>, BTreeMap<EmpireId, i64>) {
    let mut all_routes: BTreeMap<EmpireId, Vec<TradeRoute>> = BTreeMap::new();
    let mut all_income: BTreeMap<EmpireId, i64> = BTreeMap::new();

    for empire_id in self.empires.keys().copied() {
        let mut empire_routes = Vec::new();
        let mut empire_total = 0i64;

        // Get empire colony stars, sorted for determinism
        let colony_stars: BTreeSet<StarId> = self.colonies
            .values()
            .filter(|c| c.owner == empire_id)
            .map(|c| c.star)
            .collect();

        if colony_stars.len() < 2 {
            all_routes.insert(empire_id, empire_routes);
            all_income.insert(empire_id, empire_total);
            continue;
        }

        // Pair up connected colonies that have trade links
        let star_vec: Vec<StarId> = colony_stars.iter().copied().collect();
        for i in 0..star_vec.len() {
            for j in (i+1)..star_vec.len() {
                let from = star_vec[i];
                let to = star_vec[j];

                // Check connectivity
                if !self.stars_have_trade_link(empire_id, from, to) {
                    continue;
                }

                // Get population from each endpoint
                let pop_a = self.colonies.values()
                    .find(|c| c.owner == empire_id && c.star == from)
                    .map(|c| c.population as i64)
                    .unwrap_or(0);
                let pop_b = self.colonies.values()
                    .find(|c| c.owner == empire_id && c.star == to)
                    .map(|c| c.population as i64)
                    .unwrap_or(0);

                if pop_a == 0 || pop_b == 0 {
                    continue;
                }

                // Calculate base value
                let product = pop_a.saturating_mul(pop_b);
                let base_geo_mean = (product as f64).sqrt() as i64;
                let mut base_value = base_geo_mean.saturating_mul(balance::TRADE_BASE_VALUE_PER_POP);

                // Apply development bonus
                // Check for Fabrication Yards at either endpoint
                for &star in &[from, to] {
                    if let Some(colony) = self.colonies.values().find(|c| c.owner == empire_id && c.star == star) {
                        let yard_count = colony.buildings.iter()
                            .filter(|b| **b == BuildingType::FabricationYard)
                            .count() as i64;
                        base_value += base_value * yard_count * balance::TRADE_YARD_BONUS_PERMILLE / 1000;

                        // Hub bonus (shipyard or supply hub)
                        let has_hub = colony.has_shipyard() || colony.has_supply_hub();
                        if has_hub {
                            base_value += base_value * balance::TRADE_HUB_BONUS_PERMILLE / 1000;
