                    base_value += base_value * (trade_resource_count as i64) * balance::TRADE_RESOURCE_BONUS_PERMILLE / 1000;
                }

                // Determine disruption
                let mut disrupted = false;
                let mut disruption_reason = None;

                // Check blockade at either endpoint
                for &star in &[from, to] {
                    if let Some(colony) = self.colonies.values().find(|c| c.owner == empire_id && c.star == star) {
