+                        // Hub bonus (shipyard or supply hub)
+                        if colony.has_shipyard() || colony.has_supply_hub() {
+                            base_value = base_value.saturating_add(
+                                base_value * balance::TRADE_HUB_BONUS_PERMILLE / 1000,
+                            );
+                        }
+                    }
+
+                    // Tech bonus
+                    if has_trade_tech {
+                        base_value = base_value.saturating_add(
