#[test]
fn trade_income_adds_to_empire_credits() {
    let mut engine = crate::Engine::new(42);
    let player = engine.state.player_empire;
    let initial_credits = engine.state.empires.get(&player).map(|e| e.credits).unwrap_or(0);
    // Run a full end-turn to trigger trade computation
    let events = engine.apply_turn(vec![crate::Command::EndTurn]);
    let final_credits = engine.state.empires.get(&player).map(|e| e.credits).unwrap_or(0);
    let trade_income = engine.state.empire_trade_income.get(&player).copied().unwrap_or(0);
    // If trade income exists, credits should reflect it
    assert_eq!(
        final_credits,
        initial_credits + trade_income - /* maintenance */ 0,
        "credits should include trade income after end turn"
    );
    // Verify trade events were emitted
    let trade_events: Vec<_> = events.iter().filter(|e| matches!(e, crate::Event::TradeRoutesComputed { .. })).collect();
    if engine.state.empire_trade_routes.get(&player).map_or(false, |r| !r.is_empty()) {
        assert!(!trade_events.is_empty(), "TradeRoutesComputed event should be emitted");
    }
}

